/*
 * Enphase Envoy-S Metered -> Victron virtual Grid + PV
 *
 * Input:
 *   MQTT topic: envoy/json
 *
 * Enphase meter EIDs:
 *   704643328 = Production / PV
 *   704643584 = Net Consumption / Grid
 *
 * Grid sign is preserved:
 *   positive = import from grid
 *   negative = export to grid
 *
 * Freshness is handled by the watchdog rather than by comparing
 * the Envoy timestamp with the Cerbo clock. This avoids false
 * "invalid data" errors caused by clock differences or retained data.
 */

let data = msg.payload;

if (Buffer.isBuffer(data)) {
    data = data.toString("utf8");
}

if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.status({ fill: "red", shape: "dot", text: "invalid JSON" });
        node.warn("envoy/json does not contain valid JSON");
        return [null, null, null];
    }
}

if (!Array.isArray(data)) {
    node.status({ fill: "red", shape: "dot", text: "payload is not an array" });
    node.warn("Unexpected payload format on envoy/json");
    return [null, null, null];
}

function num(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : NaN;
}

function meterPower(meter) {
    if (!meter) return NaN;

    const active = num(meter.activePower);
    if (Number.isFinite(active)) return active;

    return num(meter.instantaneousDemand);
}

function bestPhase(meter) {
    if (!meter || !Array.isArray(meter.channels)) return null;

    const valid = meter.channels.filter(ch => {
        const v = num(ch.voltage);
        return Number.isFinite(v) && v > 100 && v < 300;
    });

    if (!valid.length) return null;

    valid.sort((a, b) => {
        const pa = Math.abs(
            Number.isFinite(num(a.activePower))
                ? num(a.activePower)
                : num(a.instantaneousDemand)
        ) || 0;

        const pb = Math.abs(
            Number.isFinite(num(b.activePower))
                ? num(b.activePower)
                : num(b.instantaneousDemand)
        ) || 0;

        return pb - pa;
    });

    return valid[0];
}

const pvMeter = data.find(item => Number(item.eid) === 704643328);
const gridMeter = data.find(item => Number(item.eid) === 704643584);

if (!pvMeter || !gridMeter) {
    const missing = [];
    if (!pvMeter) missing.push("PV");
    if (!gridMeter) missing.push("Grid");

    node.status({
        fill: "red",
        shape: "dot",
        text: "missing EID: " + missing.join(" + ")
    });

    node.warn("Expected Enphase EIDs were not found in envoy/json");
    return [null, null, null];
}

let pvPower = meterPower(pvMeter);
const gridPower = meterPower(gridMeter);

if (!Number.isFinite(pvPower) || !Number.isFinite(gridPower)) {
    node.status({ fill: "red", shape: "dot", text: "invalid power" });
    node.warn("Invalid activePower/instantaneousDemand in Enphase payload");
    return [null, null, null];
}

// The production CT may report a few negative watts at night.
pvPower = Math.max(0, pvPower);

const pvPhase = bestPhase(pvMeter);
const gridPhase = bestPhase(gridMeter);

const pvVoltage = num(pvPhase ? pvPhase.voltage : pvMeter.voltage);
const pvCurrent = Math.abs(num(pvPhase ? pvPhase.current : pvMeter.current));

const gridVoltage = num(gridPhase ? gridPhase.voltage : gridMeter.voltage);
const gridCurrent = Math.abs(num(gridPhase ? gridPhase.current : gridMeter.current));

let gridFrequency = num(gridPhase ? gridPhase.freq : gridMeter.freq);
if (!Number.isFinite(gridFrequency) || gridFrequency < 40 || gridFrequency > 70) {
    gridFrequency = 50;
}

const roundedPvPower = Math.round(pvPower);
const roundedGridPower = Math.round(gridPower);

// ---------- Grid virtual meter ----------
const gridMsg = {
    payload: {
        "/Ac/Power": roundedGridPower,
        "/Ac/L1/Power": roundedGridPower,
        "/Ac/Frequency": Number(gridFrequency.toFixed(2)),
        "/Connected": 1,
        "/ErrorCode": 0
    }
};

if (Number.isFinite(gridVoltage) && gridVoltage > 100 && gridVoltage < 300) {
    gridMsg.payload["/Ac/L1/Voltage"] = Number(gridVoltage.toFixed(1));
}

if (Number.isFinite(gridCurrent) && gridCurrent >= 0 && gridCurrent < 100) {
    gridMsg.payload["/Ac/L1/Current"] = Number(gridCurrent.toFixed(2));
}

const gridForwardWh = num(gridMeter.actEnergyDlvd);
if (Number.isFinite(gridForwardWh) && gridForwardWh >= 0) {
    const kWh = Number((gridForwardWh / 1000).toFixed(3));
    gridMsg.payload["/Ac/Energy/Forward"] = kWh;
    gridMsg.payload["/Ac/L1/Energy/Forward"] = kWh;
}

const gridReverseWh = num(gridMeter.actEnergyRcvd);
if (Number.isFinite(gridReverseWh) && gridReverseWh >= 0) {
    const kWh = Number((gridReverseWh / 1000).toFixed(3));
    gridMsg.payload["/Ac/Energy/Reverse"] = kWh;
    gridMsg.payload["/Ac/L1/Energy/Reverse"] = kWh;
}

// ---------- PV virtual inverter ----------
const pvMsg = {
    payload: {
        "/Ac/Power": roundedPvPower,
        "/Ac/L1/Power": roundedPvPower,
        "/StatusCode": roundedPvPower > 0 ? 7 : 8,
        "/ErrorCode": 0,
        "/Connected": 1
    }
};

if (Number.isFinite(pvVoltage) && pvVoltage > 100 && pvVoltage < 300) {
    pvMsg.payload["/Ac/L1/Voltage"] = Number(pvVoltage.toFixed(1));
}

if (Number.isFinite(pvCurrent) && pvCurrent >= 0 && pvCurrent < 100) {
    pvMsg.payload["/Ac/L1/Current"] = Number(pvCurrent.toFixed(2));
}

// Keep the same energy handling as the PV-only flow that is already working.
const pvForwardWh = num(pvMeter.actEnergyDlvd);
if (Number.isFinite(pvForwardWh) && pvForwardWh >= 0) {
    const kWh = Number((pvForwardWh / 1000).toFixed(3));
    pvMsg.payload["/Ac/Energy/Forward"] = kWh;
    pvMsg.payload["/Ac/L1/Energy/Forward"] = kWh;
}

// Any valid live MQTT message resets the watchdog.
const heartbeatMsg = {
    payload: true,
    topic: "enphase-valid"
};

node.status({
    fill: "green",
    shape: "dot",
    text:
        roundedGridPower + " W grid · " +
        roundedPvPower + " W PV · Cerbo MQTT"
});

return [gridMsg, pvMsg, heartbeatMsg];

const gridMsg = {
    payload: {
        "/Ac/Power": 0,
        "/Ac/L1/Power": 0,
        "/Ac/Frequency": 50,
        "/Connected": 0,
        "/ErrorCode": 0
    }
};

const pvMsg = {
    payload: {
        "/Ac/Power": 0,
        "/Ac/L1/Power": 0,
        "/StatusCode": 8,
        "/ErrorCode": 0,
        "/Connected": 0
    }
};

node.status({
    fill: "red",
    shape: "ring",
    text: "no envoy/json for 15 s"
});

return [gridMsg, pvMsg];
